package io.github.astelev.around_planet.space;
import java.util.*;
/** Moving sphere intersections followed by independent, primary-relative Kepler conics. */
public final class PatchedConics {
    public record Leg(SpaceTrajectory path,long from,long until,boolean transition){}
    public record Flight(List<Leg> legs,SpaceTrajectory finalPath,boolean solarImpact){public Flight(List<Leg> legs,SpaceTrajectory finalPath){this(legs,finalPath,false);}public Flight{legs=List.copyOf(legs);}}
    public static SpaceTrajectory change(SpaceTrajectory path,long tick,CelestialSystem system){var global=system.global(path.primary(),path.at(tick),tick);String next=CelestialSystem.MOON.equals(path.primary())?CelestialSystem.EARTH:CelestialSystem.SUN.equals(path.primary())?CelestialSystem.EARTH:path.at(tick).position().length()>=system.earthSoi()-1?CelestialSystem.SUN:CelestialSystem.MOON;return new SpaceTrajectory(next,tick,system.relative(next,global,tick),system.mu(next));}
    public static Flight trace(SpaceTrajectory path,long from,long until,CelestialSystem system){var legs=new ArrayList<Leg>();if(system==null||!system.managed(path.primary()))return new Flight(List.of(new Leg(path,from,until,false)),path);for(int i=0;i<32;i++){long impact=solarContact(path,from,until,system);long event=transition(path,from,impact<0?until:impact,system);if(impact>=0&&(event<0||impact<=event)){legs.add(new Leg(path,from,impact,false));return new Flight(legs,path,true);}if(event<0){legs.add(new Leg(path,from,until,false));return new Flight(legs,path);}legs.add(new Leg(path,from,event,true));path=change(path,event,system);from=event;if(from>=until)return new Flight(legs,path);}throw new IllegalArgumentException("Too many sphere transitions in one prediction");}
    public static long transition(SpaceTrajectory path,long from,long until,CelestialSystem system){if(until<from)return -1;if(CelestialSystem.MOON.equals(path.primary()))return exit(path,from,until,system.soi());
        if(CelestialSystem.SUN.equals(path.primary()))return entry(path,from,until,system,CelestialSystem.EARTH);
        long outside=exit(path,from,until,system.earthSoi()),inside=entry(path,from,outside<0?until:outside,system,CelestialSystem.MOON);return inside<0?outside:outside<0?inside:Math.min(inside,outside);}
    private static long exit(SpaceTrajectory path,long from,long until,double shell){var start=path.at(from);if(start.position().length()>shell+1e-4||start.position().length()>=shell-1e-6&&start.position().dot(start.velocity())>0)return from;double end=(until-from)/20.0;if(end<=0)return -1;var ellipse=EllipticArc.of(start,path.mu());double lo=0,hi=-1;if(ellipse!=null){double seconds=ellipse.outwardCrossing(shell);if(!Double.isFinite(seconds))return -1;long tick=from+Math.max(1,(long)Math.ceil(seconds*20-1e-8));return tick<=until?tick:-1;}else{hi=Math.min(end,Math.max(.05,shell/Math.max(1,start.velocity().length())));for(int i=0;i<64&&path.afterSeconds((from-path.epochTick())/20.0+hi).position().length()<shell;i++){if(hi>=end)return -1;lo=hi;hi=Math.min(end,hi*2);}}
        if(lo>end)return -1;for(int i=0;i<48;i++){double mid=(lo+hi)/2;if(path.afterSeconds((from-path.epochTick())/20.0+mid).position().length()<shell)lo=mid;else hi=mid;}long tick=from+Math.max(1,(long)Math.ceil(hi*20-1e-8));return tick<=until?tick:-1;}
    private static long entry(SpaceTrajectory path,long from,long until,CelestialSystem system,String child){double elapsed=0,end=(until-from)/20.0;var initial=path.at(from);var m=system.childSeconds(child,from/20.0);double gap=initial.position().subtract(m.position()).length()-system.sphere(child);if(gap < -1e-5)return from;
        // An exact equatorial co-orbit has constant Moon separation; do not sample millions of near-misses.
        var circular=EllipticArc.of(initial,path.mu());double orbitRadius=system.orbitRadius(child);if(circular!=null&&Math.abs(path.mu()-system.mu(path.primary()))<system.mu(path.primary())*1e-12&&Math.abs(circular.periapsis().length()-orbitRadius)<orbitRadius*1e-12&&Math.abs(circular.apoapsis().length()-orbitRadius)<orbitRadius*1e-12&&Math.abs(initial.position().z())<orbitRadius*1e-12&&Math.abs(initial.velocity().z())<1e-9&&initial.position().cross(initial.velocity()).z()<0)return -1;
        // Outside Earth the acceleration bound is finite. Conservative steps cannot skip a narrow encounter.
        double acceleration=system.mu(path.primary())/(system.radius(path.primary())*system.radius(path.primary()))+system.mu(path.primary())/(system.orbitRadius(child)*system.orbitRadius(child));
        for(int i=0;i<8192;i++){var state=path.afterSeconds((from-path.epochTick())/20.0+elapsed);double inner=system.orbitRadius(child)-system.sphere(child),outer=system.orbitRadius(child)+system.sphere(child),radius=state.position().length();if(radius<inner-.001||radius>outer+.001){var ellipse=EllipticArc.of(state,path.mu());if(ellipse!=null){double jump=radius<inner?ellipse.outwardCrossing(inner):ellipse.inwardCrossing(outer);if(!Double.isFinite(jump)||elapsed+jump>end)return -1;if(jump>.00001){elapsed+=jump;continue;}}else if(radius>outer&&state.position().dot(state.velocity())>=0)return -1;}var moon=system.childSeconds(child,from/20.0+elapsed);var relative=state.position().subtract(moon.position());gap=relative.length()-system.sphere(child);var v=state.velocity().subtract(moon.velocity());if(gap<=.001&&relative.dot(v)<0){long tick=from+Math.max(1,(long)Math.ceil(elapsed*20));return tick<=until?tick:-1;}if(elapsed>=end)return -1;if(gap<=.001){elapsed=Math.min(end,elapsed+.05);continue;}double speed=v.length(),step=.8*2*Math.max(.00001,gap)/(speed+Math.sqrt(speed*speed+2*acceleration*Math.max(.00001,gap)));if(step<1e-7)return -1;elapsed=Math.min(end,elapsed+step);}
        throw new IllegalArgumentException("Encounter search budget exceeded");
    }
    /** Earliest photosphere contact, including a shallow ellipse or a fast open transit. */
    public static long solarContact(SpaceTrajectory path,long from,long until,CelestialSystem system){
        if(system==null||!CelestialSystem.SUN.equals(path.primary())||until<from)return -1;
        double shell=system.solarDestructionRadius();var start=path.at(from);if(start.position().length()<=shell)return from;
        var ellipse=EllipticArc.of(start,path.mu());if(ellipse!=null){double seconds=ellipse.inwardCrossing(shell);if(!Double.isFinite(seconds))return -1;long tick=from+Math.max(1,(long)Math.ceil(seconds*20-1e-8));return tick<=until?tick:-1;}
        if(start.position().dot(start.velocity())>=0)return -1;
        if(path.mu()>0){var h=start.position().cross(start.velocity());var eccentricity=start.velocity().cross(h).scale(1/path.mu()).subtract(start.position().scale(1/start.position().length())).length();double periapsis=h.dot(h)/(path.mu()*(1+eccentricity));if(periapsis>=shell)return -1;}
        double elapsed=0,end=(until-from)/20.0,acceleration=path.mu()/(shell*shell);
        for(int i=0;i<8192;i++){var state=path.afterSeconds((from-path.epochTick())/20.0+elapsed);double gap=state.position().length()-shell;
            if(gap<=.001){long tick=from+Math.max(1,(long)Math.ceil(elapsed*20));return tick<=until?tick:-1;}
            if(elapsed>=end||state.position().dot(state.velocity())>=0)return -1;
            double speed=state.velocity().length(),step=.8*2*gap/(speed+Math.sqrt(speed*speed+2*acceleration*gap));if(step<1e-8)return -1;elapsed=Math.min(end,elapsed+step);
        }throw new IllegalArgumentException("Solar contact search budget exceeded");
    }
    private PatchedConics(){}
}
